private String reversed(String str) {
    char[] arr = str.toCharArray();
    int left = 0, right = arr.length - 1;
    while (left < right) {
        char temp = arr[left];
        arr[left++] = arr[right];
        arr[right--] = temp;
    }
    return new String(arr);
}

public static int countOilDeposits(char[][] grid) {
    int row = grid.length;
    int col = grid[0].length;
    int oilCount = 0;

    for (int r = 0; r < row; r++) {
        for (int c = 0; c < col; c++) {
            if (grid[r][c] == '@') {
                oilCount++;
                exploreOil(r, c, grid);
            }
        }
    }

    return oilCount;
}

private static void exploreOil(int x, int y, char[][] grid) {
    Stack<int[]> stack = new Stack<>();
    stack.push(new int[]{x, y});

    while (!stack.isEmpty()) {
        int[] pos = stack.pop();
        int i = pos[0];
        int j = pos[1];

        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '*') {
            continue;
        }

        grid[i][j] = '@'; // Mark the visited oil as visited
        stack.push(new int[]{i - 1, j}); // Explore up
        stack.push(new int[]{i + 1, j}); // Explore down
        stack.push(new int[]{i, j - 1}); // Explore left
        stack.push(new int[]{i, j + 1}); // Explore right
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }

    if (N == 0) {
        return 1; // 0 triangles can divide the plane into 1 region
    }

    // If N is odd, the maximum number of regions is N^k + sqrt(N)
    // If N is even, the maximum number of regions is N^k + N/2
    if (N % 2 == 0) {
        return (int) (Math.pow(N, 0.5) + N / 2.0);
    } else {
        return (int) (Math.pow(N, 0.5) + (int) (Math.sqrt(N)));
    }
}

