public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0; // Return 0 for empty array or null array
    }

    int maxSubSum = nums[0];
    int minSubSum = nums[0];

    int overallMax = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        maxSubSum = Math.max(num, maxSubSum + num);
        minSubSum = Math.min(num, minSubSum + num);

        overallMax = Math.max(overallMax, Math.max(maxSubSum, -minSubSum));
    }

    return overallMax;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = {1, 1};
    while (fib[fib.length - 1] < k) {
        fib = new int[fib.length + 1];
        fib[fib.length - 2] = fib[fib.length - 1] + fib[fib.length - 2];
    }
    int count = 0;
    for (int i = fib.length - 2; i >= 0; i--) {
        while (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
