    for (int i = Math.max(0, low); i <= high; i++) {
        if (isStepping(i)) {
            steppingNumbers.add(i);
        }
    }
    steppingNumbers.sort(Integer::compare);
    return steppingNumbers;
}

private static boolean isStepping(int number) {
    String numStr = String.valueOf(number);
    int length = numStr.length();
    for (int i = 1; i < length; i++) {
        int prevDigit = numStr.charAt(i - 1) - '0';
        int currentDigit = numStr.charAt(i) - '0';
        if (Math.abs(currentDigit - prevDigit) != 1) {
            return false;
        }
    }
    return true;
}

public static int countDigitOne(int n) {
