    }

    // Reverse the string to maintain the correct order
    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if(n == 0 || n == 1) {
        return A.length;
    }
    Map<Integer, Set<Integer>> map = new HashMap<>();
    for(int i = 0; i < n; i++) {
        map.put(A[i], new HashSet<>());
    }
    for(int i = 0; i < n - 1; i++) {
        if(!NumberUtil.isPerfectSquare(A[i] + A[i + 1])) {
            return 0;
        }
        map.get(A[i]).add(A[i + 1]);
        map.get(A[i + 1]).add(A[i]);
    }
    return map.get(map.keySet().iterator().next()).size();
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Fill the left array
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            left[i] = -1;
        } else {
            left[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack for next phase
    stack.clear();

    // Fill the right array
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            right[i] = n;
        } else {
            right[i] = stack.peek();
        }
        stack.push(i);
    }

    // Calculate the area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        maxArea = Math.max(maxArea, heights[i] * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return new int[0];
        }

        int rows = mat.length;
        int cols = mat[0].length;
        int[] result = new int[rows * cols];
        int[] direction = {0, -1}; // Right, Up
        int r = 0, c = 0;
        int idx = 0;

        while (idx < result.length) {
            result[idx++] = mat[r][c];

            int nr = r + direction[0];
            int nc = c + direction[1];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                r = nr;
                c = nc;
            } else {
                if (direction[0] == 1) {
                    // Change direction to Up
                    direction = {0, 1};
                } else if (direction[0] == 0) {
                    // Change direction to Right
                    direction = {1, 0};
                }

                r += direction[0];
                c += direction[1];
            }
        }

        Arrays.sort(result);
        return result;
    }

public static int findSmallestInteger(int n) {
    // Separate digits of n
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }
    Collections.sort(digits, Collections.reverseOrder());

    // Iterate through all permutations
    for (int i = 0; i < digits.size(); i++) {
        int[] perm = digits.stream()
                .mapToInt(Integer::intValue)
                .toArray();
        // Swap i-th and last non-zero digit
        int j = digits.indexOf(Collections.max(perm));
        if (j != Collections.size() - 1) {
            int temp = perm[i];
            perm[i] = perm[j];
            perm[j] = temp;
            // Form the smallest permutation
            int smallest = 0;
            for (int x : perm) {
                smallest = smallest * 10 + x;
            }
            return smallest;
        }
    }
    // Return -1 if no valid permutation is found
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> centerSymmetricNumbers = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            StringBuilder symmetric = new StringBuilder();
            symmetric.append("0");
            for (int j = 0; j < n - 2 * i - 1; j++) {
                symmetric.append(i % 2 == 0 ? "1" : "0");
            }
            symmetric.append("0");
            centerSymmetricNumbers.add(symmetric.toString());
        }

        return centerSymmetricNumbers;
    }

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3 || (points[0][0] == points[1][0] && points[1][0] == points[2][0] || 
        points[0][1] == points[1][1] && points[1][1] == points[2][1])) {
        throw new IllegalArgumentException("The input points do not form a valid boomerang.");
    }

    // Calculate the slope of the line segments
    double slope1 = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the points are collinear
    if (slope1 == slope2) {
        throw new IllegalArgumentException("The input points form a line and are not collinear.");
    }

    // Calculate the expected slope for a boomerang
    double expectedSlope = ((points[1][0] - points[0][0]) * (points[2][1] - points[0][1])) 
                            / ((points[2][0] - points[0][0]) * (points[1][0] - points[0][0]));

    // Determine if the points form a boomerang
    return slope1 != expectedSlope && slope2 != expectedSlope;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    PriorityQueue<Long> pq = new PriorityQueue<>();
    pq.offer(1L);
    Set<Long> visited = new HashSet<>();
    visited.add(1L);

    for (int i = 1; i < n; i++) {
        long currUgly = pq.poll();

        for (long nextUgly : new long[]{currUgly * 2, currUgly * 3, currUgly * 5}) {
            if (!visited.contains(nextUgly)) {
                pq.offer(nextUgly);
                visited.add(nextUgly);
            }
        }
    }

    return (int) pq.peek();
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
        if (n <= 0) {
            return Collections.emptyList();
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            search(result, i, n);
        }
        return result;
    }

private static void search(List<Integer> result, int start, int _max) {
        if (start >= _max) {
            return;
        }
        result.add(start);
        for (int i = 0; i <= 9; i++) {
            int next = start * 10 + i;
            if (next > _max) {
                break;
            }
            search(result, next, _max);
        }
    }

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueSet = new HashSet<>();
    // Iterate through each number in the array and add it to the set
    for (int number : nums) {
        uniqueSet.add(number);
    }
    // Calculate the sum of all elements in the set
    int sum = 0;
    for (int number : uniqueSet) {
        sum += number;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int sum = 0;
    if (n < 1) {
        throw new IllegalArgumentException("Input should be a positive integer.");
    }
    for (int i = 1; sum + i * i <= n; i++) {
        sum += i * i;
        if (sum == n) {
            return i;
        }
    }
    return -1; // If no perfect square numbers are found, return -1
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split("\\s+");

    for (int i = words.length - 1; i >= 0; i--) {
        result.append(words[i]);
        if (i > 0) {
            result.append(" ");
        }
    }

    return result.toString();
}
